# Homebrew formula for magika.
#
# GENERATED by rules_brew -- do not edit by hand;
# the next release overwrites this file.
class Magika < Formula
  desc "File-content identification with deep learning (the Google magika first-party Rust port)"
  homepage "https://google.github.io/magika/"
  # Platform choice lives in the argument, not in an on_macos block:
  # brew does not allow `url`/`sha256` inside an on_system block.
  # macOS is one universal (arm64 + x86_64) binary, so it needs no arch split.
  url on_system_conditional(
    macos: "https://github.com/qzmfranklin/homebrew-tap/releases/download/magika-1.2.0-dev/magica-darwin-universal.tar.xz",
    linux: on_arch_conditional(
      arm:   "https://github.com/qzmfranklin/homebrew-tap/releases/download/magika-1.2.0-dev/magica-linux-arm64.tar.xz",
      intel: "https://github.com/qzmfranklin/homebrew-tap/releases/download/magika-1.2.0-dev/magica-linux-amd64.tar.xz",
    ),
  )
  version "1.2.0-dev"
  sha256 on_system_conditional(
    macos: "1d5edbf09a5d1f331bb28012cc718b6f8e771ea80589c101a8a6f674dbb533e2",
    linux: on_arch_conditional(
      arm:   "2e1ce6f20d2b4f895fe8825222a8406dfb99fbcdea7dcc54e5b92b6b336f24f3",
      intel: "d59bc985664e261beb3f9f4399d425c8ffd08aeea322790a7ee9bed509aa55ad",
    ),
  )
  license :cannot_represent

  def install
    bin.install "magica"

    # Ad-hoc codesign on macOS. This is INTENTIONAL and load-bearing, not a
    # workaround: the binary is unsigned, and macOS refuses to exec an unsigned
    # or stale-signed Mach-O. Writing the file also invalidates any prior
    # signature, so it must be re-signed after install.
    #
    # chmod first: Homebrew stages files read-only, and both xattr and codesign
    # need to WRITE to the binary (xattr fails with EACCES otherwise).
    if OS.mac?
      chmod 0755, bin/"magica"
      system "/usr/bin/xattr", "-cr", bin/"magica"
      system "/usr/bin/codesign", "--force", "--sign", "-", bin/"magica"
    end
  end

  def post_install
    linked = HOMEBREW_PREFIX/"bin/magica"
    if linked.exist? && !linked.symlink?
      opoo <<~EOS
        Replacing a non-Homebrew magica at #{linked}.
        That file was almost certainly left by the legacy install script.
        The Homebrew-managed magica is now the one on your PATH.
      EOS
      linked.unlink
    end

    # Idempotent, and also repairs the case where the legacy binary was
    # deleted by hand: brew never created the symlink, so the tool was
    # missing from PATH entirely.
    linked.make_relative_symlink(bin/"magica") unless linked.symlink?
  end


  def caveats
    on_linux do
      <<~EOS
        magika ships as a single prebuilt binary per arch (the identification model
        is embedded — no runtime downloads) and runs on ubuntu22 and newer
        (glibc >= 2.35). On hosts with glibc < 2.39 (Ubuntu 22.04 and older),
        Homebrew adds gcc and glibc as implicit dependencies to every formula and
        would build them from source; magika's formula carries no real dependencies,
        so install it there with:

          brew install --ignore-dependencies magika

        On glibc >= 2.39 hosts (Ubuntu 24.04+, Homebrew's own supported set),
        plain `brew install magika` works with no extra pulls.
      EOS
    end
  end

  test do
    # The usage line survives argument changes; the identification assert runs the
    # REAL model (the embedded tract runtime) — the strongest cheap formula test.
    assert_match(/Usage: magica/, shell_output("#{bin}/magica --help"))
    (testpath/"probe.rs").write("fn main() {}\n")
    assert_match(/Rust source/, shell_output("#{bin}/magica probe.rs"))
  end
end
